/**
 * ENN-233 — Blog pack for Nina Studio: draft filter, gated bodies, inject discipline.
 * Run: npx tsx scripts/assert-nina-blog-source.ts
 * (expects npm run build:nina-blog already run, or generated file present)
 */
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { BLOG_POSTS } from '../src/data/blogPosts.generated.ts';
import { buildNinaSystemPrompt } from '../src/lib/groqChat.ts';
import {
  NINA_BLOG_POSTS,
  selectBlogPostsForText,
} from '../src/lib/ninaChatKnowledge.ts';

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));

let failed = 0;

function assert(cond: boolean, label: string) {
  if (!cond) {
    console.error('FAIL:', label);
    failed += 1;
  } else {
    console.log('PASS:', label);
  }
}

const publishedCount = BLOG_POSTS.filter((p) => !p.draft).length;
assert(
  NINA_BLOG_POSTS.length === publishedCount,
  `pack size matches published draft:false (${publishedCount})`
);
assert(
  NINA_BLOG_POSTS.every((p) => p.cite.startsWith('/news/')),
  'every pack entry cites /news/…'
);
assert(
  !NINA_BLOG_POSTS.some((p) => /benvenuto-nel-blog|ascoltare-gli-arcani/.test(p.id)),
  'draft posts excluded from pack'
);

const matto = NINA_BLOG_POSTS.find(
  (p) => p.id === 'il-coraggio-di-iniziare-il-matto'
);
assert(!!matto && matto.gated, 'Matto companion present and gated');
assert(
  !!matto &&
    (/rosa bianca|precipizio|settenari|waite/i.test(matto.body) ||
      matto.body.length > 200),
  'Matto pack body includes gated-depth facts (compact)'
);

const pamela = NINA_BLOG_POSTS.find((p) => p.id === 'pamela-colman-smith-artista');
assert(!!pamela && !pamela.gated, 'Pamela public Autori post in pack');

assert(
  selectBlogPostsForText('Com’è visivamente l’arcano del Matto?').length === 0,
  'plain Maggiori Matto ask does not inject blog (schede primary)'
);
assert(
  selectBlogPostsForText(
    'Approfondimento blog del Matto — articolo sul coraggio di iniziare'
  ).some((p) => p.id === 'il-coraggio-di-iniziare-il-matto'),
  'blog/approfondimento Matto ask selects Matto article'
);
assert(
  selectBlogPostsForText('Parlami di Pamela Colman Smith / Pixie').some(
    (p) => p.id === 'pamela-colman-smith-artista'
  ),
  'Pamela / Pixie selects Autori article'
);
assert(
  selectBlogPostsForText(
    'Approfondimento blog del Matto e articolo sul Bagatto e Pixie e Rider-Waite'
  ).length <= 2,
  'blog inject cap remains max 2'
);

const welcomeMatto = buildNinaSystemPrompt({
  mode: 'welcome',
  message: 'Approfondimento blog del Matto',
  history: [],
});
assert(
  !welcomeMatto.includes('### Blog Tarot Italia') &&
    !welcomeMatto.includes('Sintesi pack'),
  'welcome mode has no blog frame/bodies'
);

const studioPamela = buildNinaSystemPrompt({
  mode: 'studio',
  message: 'Parlami di Pamela Colman Smith Pixie nel blog',
  history: [],
});
assert(
  studioPamela.includes('Blog Tarot Italia') &&
    studioPamela.includes('pamela-colman-smith-artista') &&
    studioPamela.includes('/news/pamela-colman-smith-artista'),
  'studio Pamela ask injects blog pack + cite path'
);
assert(
  studioPamela.includes('Rispondi sempre in italiano') ||
    studioPamela.includes('SOLO in italiano'),
  'studio prompt stays Italian-only'
);

const studioMattoCard = buildNinaSystemPrompt({
  mode: 'studio',
  message: 'Com’è visivamente l’arcano del Matto?',
  history: [],
});
assert(
  studioMattoCard.includes('### 0. Il Matto'),
  'studio Maggiori Matto card still injects'
);
assert(
  !studioMattoCard.includes('### Il Coraggio di Iniziare'),
  'studio Maggiori Matto card ask does not dump Matto blog body'
);

const studioMattoBlog = buildNinaSystemPrompt({
  mode: 'studio',
  message: 'Leggi l’approfondimento blog del Matto',
  history: [],
});
assert(
  studioMattoBlog.includes('il-coraggio-di-iniziare-il-matto') ||
    studioMattoBlog.includes('/news/il-coraggio-di-iniziare-il-matto'),
  'studio blog Matto ask cites Matto article'
);

// Payload budget smoke: single-topic Studio ask stays sane with Maggiori+blog frames.
assert(
  studioPamela.length < 28_000,
  `studio Pamela prompt under soft budget (got ${studioPamela.length})`
);

const generated = readFileSync(
  path.join(root, 'src/data/ninaBlogPosts.generated.ts'),
  'utf8'
);
assert(
  generated.includes('GENERATED by scripts/build-nina-blog-pack.ts'),
  'generated file header present'
);

if (failed > 0) {
  console.error(`\n${failed} assertion(s) failed`);
  process.exit(1);
}
console.log('\nAll ENN-233 blog Studio assertions passed.');
